// Offline story authoring. Engine fields mirror world_gameplay.h; IDs stay
// decimal strings so built-in 64-bit scene identities survive JSON/browser IO.
export const SCHEMA='valwood.quest-story';
export const PROJECT_BYTE_LIMIT=16*1024*1024,GAMEPLAY_BYTE_LIMIT=2*1024*1024;
export const EVENTS=['Interact','TriggerEnter','Kill','Objective','EncounterFinished','DialogueChoice'];
export const CONDITIONS=['Flag','Counter','Quest','Encounter','EntityActive','CooldownReady','EventValue'];
export const COMPARES=['Equal','NotEqual','Less','AtLeast'];
export const ACTIONS=['SetFlag','SetCounter','AddCounter','Speak','ActivateEntity','StartEncounter','StartTraining','SetQuest','SetEncounter','SetCooldown'];
export const PROGRESS=['Inactive','Active','Complete','Failed'];
export const SHAPES=['Sphere','Box'];
export const COLLECTIONS=['entities','flags','counters','quests','encounters','triggers','dialogues','rules'];
const limits={entities:256,flags:64,counters:64,quests:32,encounters:16,triggers:64,dialogues:16,rules:128};
const clone=x=>JSON.parse(JSON.stringify(x));
const bytes=x=>new TextEncoder().encode(x).length;
const finite=(n,a,b)=>typeof n==='number'&&Number.isFinite(n)&&n>=a&&n<=b;
const integer=(n,a,b)=>Number.isInteger(n)&&finite(n,a,b);
const id=(x,zero=false)=>typeof x==='string'&&/^(0|[1-9][0-9]{0,19})$/.test(x)&&BigInt(x)<=18446744073709551615n&&(zero||x!=='0');
const text=(x,max,required=true)=>typeof x==='string'&&bytes(x)<=max&&(!required||x.trim().length>0)&&!/[\u0000-\u001f\u007f]/.test(x)&&!/[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/u.test(x);
const prose=(x,max)=>typeof x==='string'&&bytes(x)<=max&&!/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(x);
const vec=(p,lo=-1e7,hi=1e7)=>p&&['x','y','z'].every(k=>finite(p[k],lo,hi));
const find=(a,key)=>a.find(v=>v.id===key);
const native=d=>d.native;
const nodeKey=(kind,key,parent)=>kind==='line'&&parent?`${kind}:${parent}:${key}`:`${kind}:${key}`;
export const keyFor=nodeKey;

export function blank(){return {schema:SCHEMA,version:1,title:'Untitled story',logline:'',chapters:[{id:'chapter_1',title:'Chapter 1',summary:''}],beats:[],layout:{positions:{}},native:{name:'Untitled story',...Object.fromEntries(COLLECTIONS.map(k=>[k,[]]))}};}
export function nextId(d){const used=new Set();for(const k of COLLECTIONS)for(const v of native(d)[k]){used.add(v.id);if(k==='quests')for(const o of v.objectives)used.add(o.id);if(k==='dialogues')for(const l of v.lines)used.add(l.id);}let n=1n;while(used.has(String(n)))n++;return String(n);}
function chapter(d,c){return d.chapters.some(x=>x.id===c)?c:d.chapters[0]?.id||'';}
function pos(d,kind,key,parent){d.layout.positions[nodeKey(kind,key,parent)]={x:80+Object.keys(d.layout.positions).length%4*300,y:80+Math.floor(Object.keys(d.layout.positions).length/4)*200};}
const capacity=(a,max,label)=>{if(a.length>=max)throw new Error(`${label} limit reached (${max}).`);};
export function makeChapter(d){capacity(d.chapters,64,'Chapter');let n=1;while(d.chapters.some(c=>c.id===`chapter_${n}`))n++;const c={id:`chapter_${n}`,title:`Chapter ${n}`,summary:''};d.chapters.push(c);return c;}
export function makeBeat(d,c){capacity(d.beats,256,'Story beat');let n=1;while(d.beats.some(b=>b.id===`beat_${n}`))n++;const b={id:`beat_${n}`,chapter:chapter(d,c),title:'New story beat',body:'',next:[]};d.beats.push(b);pos(d,'beat',b.id);return b;}
export function makeEntity(d){capacity(native(d).entities,256,'Scene entity');const e={id:nextId(d),name:'Scene entity',active:true,position:{x:0,y:0,z:0}};native(d).entities.push(e);return e;}
export function makeFlag(d){capacity(native(d).flags,64,'Flag');const f={id:nextId(d),name:'New flag',initial:false};native(d).flags.push(f);return f;}
export function makeCounter(d){capacity(native(d).counters,64,'Counter');const c={id:nextId(d),name:'New counter',initial:0,minimum:0,maximum:100};native(d).counters.push(c);return c;}
export function makeRule(d){capacity(native(d).rules,128,'Rule');const r={id:nextId(d),name:'New event rule',event:'Interact',entity:'0',key:'0',once:false,cooldown:0,conditions:[],actions:[]};native(d).rules.push(r);pos(d,'rule',r.id);return r;}
export function addObjective(d,qid){const q=find(native(d).quests,qid);if(!q||q.objectives.length>=8)throw new Error('Choose a quest with fewer than eight objectives.');const c=makeCounter(d);c.name='Objective progress';c.maximum=1;const o={id:nextId(d),counter:c.id,text:'Complete the objective',required:1,event:'Objective',entity:'0'};q.objectives.push(o);return o;}
export function makeQuest(d,c){capacity(native(d).quests,32,'Quest');capacity(native(d).counters,64,'Counter');const q={id:nextId(d),name:'New quest',chapter:chapter(d,c),objectives:[]};native(d).quests.push(q);addObjective(d,q.id);pos(d,'quest',q.id);return q;}
export function makeLine(d,did){const talk=find(native(d).dialogues,did);if(!talk||talk.lines.length>=64)throw new Error('Choose a dialogue with fewer than 64 lines.');const line={id:nextId(d),text:'Write the dialogue here.',choices:[]};talk.lines.push(line);if(talk.entry==='0')talk.entry=line.id;pos(d,'line',line.id,talk.id);return line;}
export function makeDialogue(d,c){capacity(native(d).dialogues,16,'Dialogue');const talk={id:nextId(d),speaker:native(d).entities[0]?.id||'0',entry:'0',name:'New conversation',chapter:chapter(d,c),lines:[]};native(d).dialogues.push(talk);makeLine(d,talk.id);pos(d,'dialogue',talk.id);return talk;}
export function arrange(d){const rows=new Map(d.chapters.map((c,i)=>[c.id,i]));let indexes={};const place=(k,v)=>{const row=rows.get(v.chapter)||0;const n=indexes[row]||0;indexes[row]=n+1;d.layout.positions[nodeKey(k,v.id)]={x:70+n%4*310,y:80+row*480+Math.floor(n/4)*190};};for(const b of d.beats)place('beat',b);for(const q of native(d).quests)place('quest',q);for(const talk of native(d).dialogues){place('dialogue',talk);for(let i=0;i<talk.lines.length;i++)d.layout.positions[nodeKey('line',talk.lines[i].id,talk.id)]={x:(d.layout.positions[nodeKey('dialogue',talk.id)]?.x||70)+i*270,y:(d.layout.positions[nodeKey('dialogue',talk.id)]?.y||80)+170};}return d;}

// Draft import validates the bounded data shape without requiring a finished
// quest graph. This lets an author reopen an honest unfinished project.
export function validateStructure(d){
 const bad=[];const object=x=>!!x&&typeof x==='object'&&!Array.isArray(x);const str=x=>typeof x==='string'&&bytes(x)<=65536;const arr=(x,max)=>Array.isArray(x)&&x.length<=max;const fields=(x,ss=[],ns=[],bs=[])=>object(x)&&ss.every(k=>str(x[k]))&&ns.every(k=>typeof x[k]==='number'&&Number.isFinite(x[k]))&&bs.every(k=>typeof x[k]==='boolean');const vector=x=>fields(x,[],['x','y','z']);
 if(!object(d)||d.schema!==SCHEMA||d.version!==1)return ['Unsupported story project schema/version.'];
 if(!fields(d,['title','logline'])||!arr(d.chapters,64)||d.chapters.length<1||d.chapters.some(c=>!fields(c,['id','title','summary'])))bad.push('Malformed chapter/story fields.');
 if(!arr(d.beats,256)||d.beats.some(b=>!fields(b,['id','chapter','title','body'])||!arr(b.next,16)||b.next.some(x=>!str(x))))bad.push('Malformed story beats.');
 if(!object(d.layout)||!object(d.layout.positions)||Object.keys(d.layout.positions).length>4096||Object.entries(d.layout.positions).some(([k,p])=>!str(k)||!fields(p,[],['x','y'])))bad.push('Malformed editor positions.');
 const n=d.native;if(!fields(n,['name']))return [...bad,'Missing native gameplay document.'];for(const k of COLLECTIONS)if(!arr(n[k],limits[k]))bad.push(`Malformed/oversized ${k} array.`);if(bad.some(s=>s.includes('array')))return bad;
 for(const k of COLLECTIONS)for(const v of n[k])if(!fields(v,['id','name']))bad.push(`Malformed ${k} item.`);if(bad.some(s=>s.includes('item')))return bad;
 if(n.entities.some(e=>!fields(e,[],[],['active'])||!vector(e.position)))bad.push('Malformed scene entity fields.');if(n.flags.some(f=>!fields(f,[],[],['initial'])))bad.push('Malformed flag fields.');if(n.counters.some(c=>!fields(c,[],['initial','minimum','maximum'])))bad.push('Malformed counter fields.');
 if(n.quests.some(q=>(q.chapter!==undefined&&!str(q.chapter))||!arr(q.objectives,8)||q.objectives.some(o=>!fields(o,['id','counter','text','event','entity'],['required']))))bad.push('Malformed quest/objective fields.');
 if(n.encounters.some(e=>!fields(e,['arena'],[],['training'])||!arr(e.actors,16)||e.actors.some(x=>!str(x))))bad.push('Malformed encounter fields.');if(n.triggers.some(t=>!fields(t,['entity','shape'],[],['once'])||!vector(t.center)||!vector(t.extent)))bad.push('Malformed trigger fields.');
 const listShape=x=>object(x)&&arr(x.conditions,8)&&x.conditions.every(c=>fields(c,['kind','key','compare'],['value']))&&arr(x.actions,16)&&x.actions.every(a=>fields(a,['kind','key'],['value']));
 if(n.dialogues.some(t=>!fields(t,['speaker','entry'])||(t.chapter!==undefined&&!str(t.chapter))||!arr(t.lines,64)||t.lines.some(l=>!fields(l,['id','text'])||!arr(l.choices,8)||l.choices.some(c=>!fields(c,['text','next'])||!listShape(c)))))bad.push('Malformed dialogue/choice fields.');
 if(n.rules.some(r=>!fields(r,['event','entity','key'],['cooldown'],['once'])||!listShape(r)))bad.push('Malformed event rule fields.');return bad;
}
export function parseProject(source){if(typeof source!=='string'||bytes(source)>PROJECT_BYTE_LIMIT)throw new Error('Story project exceeds 16 MiB.');const d=JSON.parse(source);const errors=validateStructure(d);if(errors.length)throw new Error(errors.join('\n'));return d;}
export function validate(d){const shape=validateStructure(d);if(shape.length)return shape;try{return validateSemantic(d);}catch{return ['Malformed story values or references.'];}}
function validateSemantic(d){
 const errors=[];const bad=s=>errors.push(s);if(!d||d.schema!==SCHEMA||d.version!==1)return ['Unsupported story document. Expected valwood.quest-story version 1.'];
 if(!text(d.title,96))bad('Story title needs 1–96 UTF-8 bytes.');if(!prose(d.logline,4096))bad('Story logline exceeds 4096 UTF-8 bytes or contains controls.');
 if(!Array.isArray(d.chapters)||d.chapters.length<1||d.chapters.length>64||d.chapters.some(c=>!c||!text(c.id,64)||!text(c.title,96)||!prose(c.summary,8192))||new Set(d.chapters.map(c=>c.id)).size!==d.chapters.length)bad('Use 1–64 distinct chapters with titles and summaries.');
 if(!Array.isArray(d.beats)||d.beats.length>256)return [...errors,'Use at most 256 story beats.'];
 const chapters=new Set((d.chapters||[]).map(c=>c.id));const beatIds=new Set(d.beats.map(b=>b?.id));if(beatIds.size!==d.beats.length)bad('Story beat IDs must be unique.');
 for(const b of d.beats)if(!b||!text(b.id,64)||!text(b.title,96)||!prose(b.body,16384)||!chapters.has(b.chapter)||!Array.isArray(b.next)||b.next.length>16||b.next.some(n=>!beatIds.has(n))||new Set(b.next).size!==b.next.length)bad('A story beat has invalid text, chapter or next-beat links.');
 if(!d.layout||!d.layout.positions||typeof d.layout.positions!=='object'||Array.isArray(d.layout.positions)||Object.entries(d.layout.positions).some(([k,p])=>!text(k,128)||!p||!finite(p.x,-1e6,1e6)||!finite(p.y,-1e6,1e6)))bad('Editor positions must be finite coordinates.');
 const n=d.native;if(!n||typeof n!=='object')return [...errors,'Missing native gameplay document.'];if(!text(n.name,96))bad('Engine gameplay name needs 1–96 UTF-8 bytes.');
 const allowed=(v,keys,label)=>{if(Object.keys(v).some(k=>!keys.includes(k)))bad(`${label}: unknown fields cannot be exported safely.`);};allowed(n,['name',...COLLECTIONS],'Native gameplay');
 const known={entities:['id','name','active','position'],flags:['id','name','initial'],counters:['id','name','initial','minimum','maximum'],quests:['id','name','chapter','objectives'],encounters:['id','arena','name','training','actors'],triggers:['id','entity','name','shape','center','extent','once'],dialogues:['id','speaker','entry','name','chapter','lines'],rules:['id','name','event','entity','key','once','cooldown','conditions','actions']};for(const k of COLLECTIONS)for(const v of n[k])allowed(v,known[k],k);
 for(const k of COLLECTIONS){if(!Array.isArray(n[k])||n[k].length>limits[k])return [...errors,`${k} exceeds its engine budget (${limits[k]}).`];const seen=new Set();for(const v of n[k]){if(!v||!id(v.id)||seen.has(v.id)||!text(v.name,96))bad(`${k}: invalid/duplicate identity or name.`);seen.add(v?.id);}}
 if(errors.some(e=>e.includes('identity')))return errors;
 const ref=(k,key)=>id(key)&&!!find(n[k],key);const maybe=(k,key)=>key==='0'||ref(k,key);
 for(const e of n.entities)if(typeof e.active!=='boolean'||!vec(e.position))bad(`${e.name}: entity position/activation is invalid.`);
 for(const f of n.flags)if(typeof f.initial!=='boolean')bad(`${f.name}: flag initial value must be boolean.`);
 for(const c of n.counters)if(!integer(c.minimum,-1e6,1e6)||!integer(c.maximum,c.minimum,1e6)||!integer(c.initial,c.minimum,c.maximum))bad(`${c.name}: counter bounds or initial value are invalid.`);
 const objectiveIds=new Set(),owned=new Set();for(const q of n.quests){if(q.chapter!==undefined&&!chapters.has(q.chapter))bad(`${q.name}: missing chapter.`);if(!Array.isArray(q.objectives)||q.objectives.length<1||q.objectives.length>8){bad(`${q.name}: a quest needs 1–8 objectives.`);continue;}for(const o of q.objectives){allowed(o,['id','counter','text','required','event','entity'],'Objective');const c=find(n.counters,o?.counter);if(!o||!id(o.id)||objectiveIds.has(o.id)||!c||owned.has(o.counter)||!text(o.text,256)||!integer(o.required,1,c?.maximum||0)||!EVENTS.slice(0,5).includes(o.event)||!maybe('entities',o.entity))bad(`${q.name}: invalid objective or shared progress counter.`);objectiveIds.add(o?.id);owned.add(o?.counter);}}
 const actors=new Set();for(const e of n.encounters){if(!ref('entities',e.arena)||typeof e.training!=='boolean'||!Array.isArray(e.actors)||e.actors.length<1||e.actors.length>16){bad(`${e.name}: encounter needs an arena and 1–16 actors.`);continue;}for(const a of e.actors){if(!ref('entities',a)||actors.has(a))bad(`${e.name}: missing or shared encounter actor.`);actors.add(a);}}
 for(const t of n.triggers)if(!maybe('entities',t.entity)||!SHAPES.includes(t.shape)||!vec(t.center)||!vec(t.extent,.01,100000)||typeof t.once!=='boolean')bad(`${t.name}: invalid trigger geometry or entity.`);
 function lists(cs,as,choice,label){if(!Array.isArray(cs)||cs.length>8||!Array.isArray(as)||as.length>16){bad(`${label}: use at most 8 conditions and 16 actions.`);return;}for(const c of cs){allowed(c,['kind','key','compare','value'],'Condition');let ok=c&&CONDITIONS.includes(c.kind)&&COMPARES.includes(c.compare)&&integer(c.value,-1e6,1e6);if(ok)switch(c.kind){case'Flag':ok=ref('flags',c.key)&&(c.value===0||c.value===1);break;case'Counter':ok=ref('counters',c.key);break;case'Quest':ok=ref('quests',c.key)&&integer(c.value,0,3);break;case'Encounter':ok=ref('encounters',c.key)&&integer(c.value,0,3);break;case'EntityActive':ok=ref('entities',c.key)&&(c.value===0||c.value===1);break;case'CooldownReady':ok=ref('rules',c.key)&&(c.value===0||c.value===1);break;case'EventValue':ok=!choice&&c.key==='0';break;}if(!ok)bad(`${label}: invalid condition target/value.`);}for(const a of as){allowed(a,['kind','key','value'],'Action');let ok=a&&ACTIONS.includes(a.kind)&&integer(a.value,-1e6,86400000);if(ok)switch(a.kind){case'SetFlag':ok=ref('flags',a.key)&&(a.value===0||a.value===1);break;case'SetCounter':{const c=find(n.counters,a.key);ok=!!c&&integer(a.value,c.minimum,c.maximum);break;}case'AddCounter':ok=ref('counters',a.key)&&integer(a.value,-1e6,1e6);break;case'Speak':ok=!choice&&ref('dialogues',a.key);break;case'ActivateEntity':ok=ref('entities',a.key)&&(a.value===0||a.value===1);break;case'StartEncounter':case'StartTraining':{const e=find(n.encounters,a.key);ok=!!e&&e.training===(a.kind==='StartTraining');break;}case'SetQuest':ok=ref('quests',a.key)&&integer(a.value,0,3);break;case'SetEncounter':ok=ref('encounters',a.key)&&[0,2,3].includes(a.value);break;case'SetCooldown':ok=ref('rules',a.key)&&a.value>=0;break;}if(!ok)bad(`${label}: invalid action target/value.`);}}
 let lines=0,choices=0;for(const t of n.dialogues){if(t.chapter!==undefined&&!chapters.has(t.chapter))bad(`${t.name}: missing chapter.`);if(!ref('entities',t.speaker)||!Array.isArray(t.lines)||!t.lines.length||t.lines.length>64||!find(t.lines,t.entry)){bad(`${t.name}: dialogue needs a scene speaker and existing entry line.`);continue;}const ids=new Set();for(const l of t.lines){allowed(l,['id','text','choices'],'Dialogue line');lines++;if(!id(l.id)||ids.has(l.id)||!text(l.text,2048)||!Array.isArray(l.choices)||l.choices.length>8){bad(`${t.name}: invalid dialogue line/choice budget.`);continue;}ids.add(l.id);for(const c of l.choices){allowed(c,['text','next','conditions','actions'],'Dialogue choice');choices++;if(!text(c.text,256)||!id(c.next,true)||(c.next!=='0'&&!find(t.lines,c.next)))bad(`${t.name}: invalid choice text or next-line link.`);lists(c.conditions,c.actions,true,t.name);}}const visiting=new Set(),done=new Set();let cyclic=false;function visit(key){if(done.has(key))return;if(visiting.has(key)){cyclic=true;return;}const l=find(t.lines,key);if(!l)return;visiting.add(key);for(const c of l.choices||[])if(c.next!=='0')visit(c.next);visiting.delete(key);done.add(key);}visit(t.entry);if(cyclic)bad(`${t.name}: dialogue graph has a cycle.`);if(done.size!==t.lines.length)bad(`${t.name}: dialogue has unreachable lines.`);}
 if(lines>256||choices>512)bad('Total dialogue budget exceeds 256 lines or 512 choices.');
 const eventKey=(event,key)=>{if(key==='0')return ['Interact','Kill'].includes(event);switch(event){case'TriggerEnter':return ref('triggers',key);case'Kill':case'EncounterFinished':return ref('encounters',key);case'Objective':return objectiveIds.has(key);case'DialogueChoice':return ref('dialogues',key);default:return false;}};
 for(const r of n.rules){if(!EVENTS.includes(r.event)||!maybe('entities',r.entity)||!eventKey(r.event,r.key)||typeof r.once!=='boolean'||!finite(r.cooldown,0,86400)||!Array.isArray(r.actions)||r.actions.length<1)bad(`${r.name}: invalid event/filter/cooldown or no actions.`);lists(r.conditions,r.actions,false,r.name);}
 return [...new Set(errors)];
}

export function warnings(d){if(!d?.native)return [];const n=d.native,out=[];if(n.encounters.length)out.push('Authored encounters need a supported combat host. Current game supports the existing training arena and presentation encounter only.');if(d.beats.length)out.push('Story beats, chapters and outfit notes are planning content; engine export contains typed gameplay only.');if(n.quests.some(q=>q.objectives.length>1))out.push('Active quest objectives progress concurrently. Gate events/actions with conditions for sequential story steps.');if(n.quests.length&&!n.rules.some(r=>r.actions.some(a=>a.kind==='SetQuest'))&&!n.dialogues.some(t=>t.lines.some(l=>l.choices.some(c=>c.actions.some(a=>a.kind==='SetQuest')))))out.push('No action activates a quest. Add SetQuest Active to an offer choice or event rule.');if(n.quests.some(q=>q.objectives.some(o=>['TriggerEnter','EncounterFinished'].includes(o.event))))out.push('Trigger/encounter objective matching uses event and entity, not event key. Use a key-filtered rule to set the progress counter for a specific trigger/encounter.');out.push('Live activation requires a Components manifest and matching persistent scene IDs. Dedicated playtest slices keep story runtime frozen.');return out;}
const quote=s=>'"'+s.replaceAll('\\','\\\\').replaceAll('"','\\"')+'"';
const b=x=>x?1:0;const xyz=p=>`${p.x} ${p.y} ${p.z}`;
const lists=(cs,as)=>`${cs.length}${cs.map(c=>` ${CONDITIONS.indexOf(c.kind)} ${c.key} ${COMPARES.indexOf(c.compare)} ${c.value}`).join('')} ${as.length}${as.map(a=>` ${ACTIONS.indexOf(a.kind)} ${a.key} ${a.value}`).join('')}`;
export function compile(d){const errors=validate(d);if(errors.length)throw new Error(errors.join('\n'));const n=d.native,rows=['VALWOOD_GAMEPLAY 1',`name ${quote(n.name)}`];for(const e of n.entities)rows.push(`entity ${e.id} ${quote(e.name)} ${b(e.active)} ${xyz(e.position)}`);for(const f of n.flags)rows.push(`flag ${f.id} ${quote(f.name)} ${b(f.initial)}`);for(const c of n.counters)rows.push(`counter ${c.id} ${quote(c.name)} ${c.initial} ${c.minimum} ${c.maximum}`);for(const q of n.quests)rows.push(`quest ${q.id} ${quote(q.name)} ${q.objectives.length}${q.objectives.map(o=>` ${o.id} ${o.counter} ${quote(o.text)} ${o.required} ${EVENTS.indexOf(o.event)} ${o.entity}`).join('')}`);for(const e of n.encounters)rows.push(`encounter ${e.id} ${e.arena} ${quote(e.name)} ${b(e.training)} ${e.actors.length} ${e.actors.join(' ')}`);for(const t of n.triggers)rows.push(`trigger ${t.id} ${t.entity} ${quote(t.name)} ${SHAPES.indexOf(t.shape)} ${xyz(t.center)} ${xyz(t.extent)} ${b(t.once)}`);for(const t of n.dialogues)rows.push(`dialogue ${t.id} ${t.speaker} ${t.entry} ${quote(t.name)} ${t.lines.length}${t.lines.map(l=>` ${l.id} ${quote(l.text)} ${l.choices.length}${l.choices.map(c=>` ${quote(c.text)} ${c.next} ${lists(c.conditions,c.actions)}`).join('')}`).join('')}`);for(const r of n.rules)rows.push(`rule ${r.id} ${quote(r.name)} ${EVENTS.indexOf(r.event)} ${r.entity} ${r.key} ${b(r.once)} ${r.cooldown} ${lists(r.conditions,r.actions)}`);const out=rows.join('\n')+'\n';if(bytes(out)>2*1024*1024)throw new Error('Engine gameplay export exceeds 2 MiB.');return out;}

// Tokenizer follows std::quoted exactly: a backslash escapes the next literal
// character, rather than interpreting JSON \n, \t or Unicode escape syntax.
function tokens(line){const out=[];let i=0;while(i<line.length){while(/\s/.test(line[i]||'')&&i<line.length)i++;if(i===line.length)break;let t='';if(line[i]==='"'){i++;let closed=false;while(i<line.length){let c=line[i++];if(c==='"'){closed=true;break;}if(c==='\\'){if(i===line.length)throw new Error('Unfinished quoted escape.');c=line[i++];}t+=c;}if(!closed)throw new Error('Unclosed quoted string.');if(i<line.length&&!/\s/.test(line[i]))throw new Error('Missing token separator.');}else{while(i<line.length&&!/\s/.test(line[i]))t+=line[i++];}out.push(t);}return out;}
export function parseGameplay(source){if(typeof source!=='string'||bytes(source)>2*1024*1024||source.includes('\0'))throw new Error('Gameplay file is missing or exceeds 2 MiB.');const rows=source.split(/\r?\n/).filter(l=>l.trim());if(rows.shift()?.trim()!=='VALWOOD_GAMEPLAY 1')throw new Error('Expected VALWOOD_GAMEPLAY 1.');const d=blank();d.chapters[0].title='Imported gameplay';let gotName=false;for(const row of rows){const ts=tokens(row);let at=0;const take=()=>{if(at>=ts.length)throw new Error('Truncated gameplay record.');return ts[at++];};const num=()=>{const s=take();if(!/^[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:e[+-]?[0-9]+)?$/i.test(s)||!Number.isFinite(Number(s)))throw new Error('Invalid finite numeric token.');return Number(s);};const uint=()=>{const x=take();if(!id(x,true))throw new Error('Invalid unsigned 64-bit identity.');return x;};const bool=()=>{const n=num();if(n!==0&&n!==1)throw new Error('Expected boolean 0 or 1.');return n===1;};const count=max=>{const n=num();if(!integer(n,0,max))throw new Error('Gameplay list exceeds engine budget.');return n;};const enumValue=a=>{const n=num();if(!integer(n,0,a.length-1))throw new Error('Unknown gameplay enum.');return a[n];};const vector=()=>({x:num(),y:num(),z:num()});const readLists=()=>{const conditions=[],actions=[];for(let i=count(8);i;i--)conditions.push({kind:enumValue(CONDITIONS),key:uint(),compare:enumValue(COMPARES),value:num()});for(let i=count(16);i;i--)actions.push({kind:enumValue(ACTIONS),key:uint(),value:num()});return {conditions,actions};};const tag=take();switch(tag){case'name':if(gotName)throw new Error('Duplicate gameplay name.');d.native.name=take();d.title=d.native.name;gotName=true;break;case'entity':d.native.entities.push({id:uint(),name:take(),active:bool(),position:vector()});break;case'flag':d.native.flags.push({id:uint(),name:take(),initial:bool()});break;case'counter':d.native.counters.push({id:uint(),name:take(),initial:num(),minimum:num(),maximum:num()});break;case'quest':{const q={id:uint(),name:take(),chapter:d.chapters[0].id,objectives:[]};for(let i=count(8);i;i--)q.objectives.push({id:uint(),counter:uint(),text:take(),required:num(),event:enumValue(EVENTS),entity:uint()});d.native.quests.push(q);break;}case'encounter':{const e={id:uint(),arena:uint(),name:take(),training:bool(),actors:[]};for(let i=count(16);i;i--)e.actors.push(uint());d.native.encounters.push(e);break;}case'trigger':d.native.triggers.push({id:uint(),entity:uint(),name:take(),shape:enumValue(SHAPES),center:vector(),extent:vector(),once:bool()});break;case'dialogue':{const t={id:uint(),speaker:uint(),entry:uint(),name:take(),chapter:d.chapters[0].id,lines:[]};for(let i=count(64);i;i--){const l={id:uint(),text:take(),choices:[]};for(let j=count(8);j;j--)l.choices.push({text:take(),next:uint(),...readLists()});t.lines.push(l);}d.native.dialogues.push(t);break;}case'rule':d.native.rules.push({id:uint(),name:take(),event:enumValue(EVENTS),entity:uint(),key:uint(),once:bool(),cooldown:num(),...readLists()});break;default:throw new Error(`Unknown gameplay record: ${tag}`);}if(at!==ts.length)throw new Error(`Trailing tokens in ${tag} record.`);}if(!gotName)throw new Error('Missing gameplay name.');const errors=validate(d);if(errors.length)throw new Error(errors.join('\n'));arrange(d);return d;}

export function deleteItem(d,kind,key,parent){
 if(kind==='beat'){d.beats=d.beats.filter(b=>b.id!==key);for(const b of d.beats)b.next=b.next.filter(n=>n!==key);delete d.layout.positions[nodeKey(kind,key)];return {ok:true,error:''};}
 if(kind==='chapter'){if(d.chapters.length===1)return {ok:false,error:'Keep at least one chapter.'};if(d.beats.some(b=>b.chapter===key)||[...d.native.quests,...d.native.dialogues].some(v=>v.chapter===key))return {ok:false,error:'Move this chapter’s beats, quests and conversations before deleting it.'};d.chapters=d.chapters.filter(c=>c.id!==key);return {ok:true,error:''};}
 const map={entity:'entities',flag:'flags',counter:'counters',quest:'quests',encounter:'encounters',trigger:'triggers',dialogue:'dialogues',rule:'rules'};
 if(kind==='line'){const matches=d.native.dialogues.filter(x=>(!parent||x.id===parent)&&x.lines.some(l=>l.id===key));if(matches.length!==1)return {ok:false,error:matches.length?'Choose the parent conversation for this line.':'Line not found.'};const t=matches[0];if(t.entry===key||t.lines.some(l=>l.choices.some(c=>c.next===key)))return {ok:false,error:'Change the entry and incoming choice links before deleting this line.'};t.lines=t.lines.filter(l=>l.id!==key);delete d.layout.positions[nodeKey(kind,key,t.id)];return {ok:true,error:''};}
 if(kind==='objective'){const q=d.native.quests.find(q=>q.objectives.some(o=>o.id===key));if(!q)return {ok:false,error:'Objective not found.'};if(q.objectives.length===1)return {ok:false,error:'A quest needs at least one objective.'};if(d.native.rules.some(r=>r.event==='Objective'&&r.key===key))return {ok:false,error:'Remove rules targeting this objective first.'};q.objectives=q.objectives.filter(o=>o.id!==key);return {ok:true,error:''};}
 const collection=map[kind];if(!collection)return {ok:false,error:'Unknown item type.'};const n=d.native,allLists=[...n.rules,...n.dialogues.flatMap(t=>t.lines.flatMap(l=>l.choices))];const conditionTargets={entity:'EntityActive',flag:'Flag',counter:'Counter',quest:'Quest',encounter:'Encounter',rule:'CooldownReady'};const actionTargets={entity:['ActivateEntity'],flag:['SetFlag'],counter:['SetCounter','AddCounter'],quest:['SetQuest'],encounter:['StartEncounter','StartTraining','SetEncounter'],dialogue:['Speak'],rule:['SetCooldown']};let referenced=allLists.some(v=>v.conditions.some(c=>c.kind===conditionTargets[kind]&&c.key===key)||v.actions.some(a=>(actionTargets[kind]||[]).includes(a.kind)&&a.key===key));
 if(kind==='entity')referenced||=n.quests.some(q=>q.objectives.some(o=>o.entity===key))||n.encounters.some(e=>e.arena===key||e.actors.includes(key))||n.triggers.some(t=>t.entity===key)||n.dialogues.some(t=>t.speaker===key)||n.rules.some(r=>r.entity===key);
 if(kind==='counter')referenced||=n.quests.some(q=>q.objectives.some(o=>o.counter===key));if(kind==='trigger')referenced||=n.rules.some(r=>r.event==='TriggerEnter'&&r.key===key);if(kind==='encounter')referenced||=n.rules.some(r=>['Kill','EncounterFinished'].includes(r.event)&&r.key===key);if(kind==='dialogue')referenced||=n.rules.some(r=>r.event==='DialogueChoice'&&r.key===key);if(kind==='quest'){const ids=new Set(find(n.quests,key)?.objectives.map(o=>o.id)||[]);referenced||=n.rules.some(r=>r.event==='Objective'&&ids.has(r.key));}
 if(referenced)return {ok:false,error:'This item is referenced. Remove or change its incoming references first.'};d.native[collection]=n[collection].filter(v=>v.id!==key);delete d.layout.positions[nodeKey(kind,key)];return {ok:true,error:''};
}

export function summary(d){const n=d.native;return {chapters:d.chapters.length,beats:d.beats.length,quests:n.quests.length,objectives:n.quests.reduce((s,q)=>s+q.objectives.length,0),dialogues:n.dialogues.length,lines:n.dialogues.reduce((s,t)=>s+t.lines.length,0),choices:n.dialogues.reduce((s,t)=>s+t.lines.reduce((a,l)=>a+l.choices.length,0),0),rules:n.rules.length,entities:n.entities.length};}

export function example(){const d=blank();d.title=d.native.name='A father at Grandstone';d.logline='A modern father enters Valwood. Earn the dwarves’ trust before the later knight transformation.';d.chapters=[{id:'modern_dad',title:'01 · An ordinary father',summary:'Modern everyday clothes, familiar family life, then an unexpected crossing. Outfit and cinematic work are planning notes.'},{id:'grandstone',title:'02 · The doors of Grandstone',summary:'Meet the gatekeeper, inspect the oath stone, and return for the dwarves’ welcome.'},{id:'knight',title:'03 · An oath and armor',summary:'Later hero production milestone: keep the same face/body and equip modular knight armor. This beat does not change the model in game.'}];d.beats=[{id:'home',chapter:'modern_dad',title:'A normal day',body:'Introduce the father and what he stands to lose. Everyday modern clothes. Keep the family moment grounded.',next:['arrival']},{id:'arrival',chapter:'grandstone',title:'Snow before the gate',body:'The grand entrance frames a lone father. The gatekeeper offers a simple test of respect.',next:['oath']},{id:'oath',chapter:'knight',title:'A promise worth keeping',body:'After earning trust, plan the same hero’s eventual knight equipment. Armor transformation is a future character integration task.',next:[]}];
 const guide='9007199254740993',stone='18446744073709551614';d.native.entities=[{id:guide,name:'Grandstone gatekeeper',active:true,position:{x:0,y:0,z:0}},{id:stone,name:'Oath stone marker',active:true,position:{x:8,y:0,z:0}}];d.native.flags=[{id:'10',name:'Offer accepted',initial:false},{id:'11',name:'Welcome paid',initial:false}];d.native.counters=[{id:'20',name:'Oath stone inspected',initial:0,minimum:0,maximum:1},{id:'21',name:'Story reward coins',initial:0,minimum:0,maximum:1000000}];d.native.quests=[{id:'30',name:'A welcome at Grandstone',chapter:'grandstone',objectives:[{id:'31',counter:'20',text:'Inspect the oath stone beside the gate',required:1,event:'Interact',entity:stone}]}];
 d.native.dialogues=[{id:'40',speaker:guide,entry:'41',name:'The gatekeeper’s offer',chapter:'grandstone',lines:[{id:'41',text:'You carry no banner, traveler. Show respect to the oath stone, then return. Will you accept?',choices:[{text:'I will honor your custom.',next:'42',conditions:[{kind:'Flag',key:'10',compare:'Equal',value:0}],actions:[{kind:'SetFlag',key:'10',value:1},{kind:'SetQuest',key:'30',value:1}]},{text:'I need more time.',next:'0',conditions:[],actions:[]}]},{id:'42',text:'The stone stands beside the gate. Return when you have read its promise.',choices:[{text:'I will return.',next:'0',conditions:[],actions:[]}]}]},{id:'60',speaker:guide,entry:'61',name:'A dwarven welcome',chapter:'grandstone',lines:[{id:'61',text:'A promise matters more than a banner. Grandstone welcomes you. Take these 25 coins for the road.',choices:[{text:'Thank you. I will remember.',next:'0',conditions:[],actions:[]}]}]},{id:'70',speaker:guide,entry:'71',name:'The stone awaits',chapter:'grandstone',lines:[{id:'71',text:'Read the oath stone beside the gate, then speak with me again.',choices:[{text:'I understand.',next:'0',conditions:[],actions:[]}]}]}];
 const rule=(id,name,conditions,actions)=>({id,name,event:'Interact',entity:guide,key:'0',once:false,cooldown:0,conditions,actions});d.native.rules=[rule('50','Offer the gatekeeper’s test',[{kind:'Flag',key:'10',compare:'Equal',value:0}],[{kind:'Speak',key:'40',value:1}]),rule('51','Pay the welcome once',[{kind:'Quest',key:'30',compare:'Equal',value:2},{kind:'Flag',key:'11',compare:'Equal',value:0}],[{kind:'SetFlag',key:'11',value:1},{kind:'AddCounter',key:'21',value:25},{kind:'Speak',key:'60',value:1}]),rule('52','Remind the traveler',[{kind:'Quest',key:'30',compare:'Equal',value:1}],[{kind:'Speak',key:'70',value:1}])];arrange(d);return d;}

// A CPU rehearsal mirrors the bounded gameplay transaction; no game/project
// writes, entity spawning, combat, cinematics or engine save migration implied.
export function createPreview(d){const errors=validate(d);if(errors.length)throw new Error(errors.join('\n'));const n=clone(d.native);return {native:n,entities:Object.fromEntries(n.entities.map(e=>[e.id,e.active])),flags:Object.fromEntries(n.flags.map(f=>[f.id,+f.initial])),counters:Object.fromEntries(n.counters.map(c=>[c.id,c.initial])),quests:Object.fromEntries(n.quests.map(q=>[q.id,0])),encounters:Object.fromEntries(n.encounters.map(e=>[e.id,{progress:0,defeated:[]} ])),rules:Object.fromEntries(n.rules.map(r=>[r.id,{fired:false,cooldown:0}])),triggers:Object.fromEntries(n.triggers.map(t=>[t.id,{inside:false,fired:false}])),dialogue:'0',line:'0',queue:[],commands:[],log:[],time:0,player:{x:1e6,y:1e6,z:1e6}};}
const compare=(a,op,v)=>op==='Equal'?a===v:op==='NotEqual'?a!==v:op==='Less'?a<v:a>=v;
function meets(s,cs,e={value:0}){return cs.every(c=>{let v=0;switch(c.kind){case'Flag':v=s.flags[c.key];break;case'Counter':v=s.counters[c.key];break;case'Quest':v=s.quests[c.key];break;case'Encounter':v=s.encounters[c.key].progress;break;case'EntityActive':v=+s.entities[c.key];break;case'CooldownReady':v=+(s.rules[c.key].cooldown<=0);break;case'EventValue':v=e.value;break;}return compare(v,c.compare,c.value);});}
export function previewLine(s){return find(s.native.dialogues,s.dialogue)?.lines.find(l=>l.id===s.line)||null;}
export function previewChoices(s){return (previewLine(s)?.choices||[]).map((c,index)=>({...c,index})).filter(c=>meets(s,c.conditions));}
function speak(s,key,line){const t=find(s.native.dialogues,key);if(!s.entities[t.speaker])return;s.dialogue=key;s.line=line||t.entry;const l=previewLine(s);s.commands.push({kind:'Speak',entity:t.speaker,key,node:s.line,text:l.text});}
function action(s,a){switch(a.kind){case'SetFlag':s.flags[a.key]=a.value;break;case'SetCounter':case'AddCounter':{const c=find(s.native.counters,a.key);s.counters[a.key]=Math.max(c.minimum,Math.min(c.maximum,a.kind==='SetCounter'?a.value:s.counters[a.key]+a.value));break;}case'SetQuest':s.quests[a.key]=a.value;s.commands.push({kind:'QuestChanged',key:a.key,value:a.value});break;case'SetEncounter':s.encounters[a.key].progress=a.value;s.commands.push({kind:'EncounterChanged',key:a.key,value:a.value});break;case'SetCooldown':s.rules[a.key].cooldown=a.value*.001;break;case'Speak':speak(s,a.key);break;case'ActivateEntity':s.entities[a.key]=!!a.value;if(!a.value&&find(s.native.dialogues,s.dialogue)?.speaker===a.key){s.commands.push({kind:'EndDialogue',key:s.dialogue});s.dialogue=s.line='0';}s.commands.push({kind:'ActivateEntity',entity:a.key,value:a.value});break;case'StartEncounter':case'StartTraining':{const e=find(s.native.encounters,a.key),state=s.encounters[a.key];if(state.progress===1)break;state.progress=1;state.defeated=[];for(const actor of e.actors){s.entities[actor]=true;s.commands.push({kind:'ActivateEntity',entity:actor,key:e.id,value:1});}s.commands.push({kind:a.kind,entity:e.arena,key:e.id,value:1});break;}}}
function normalize(s,e){if(!e||!EVENTS.includes(e.kind))throw new Error('Choose a supported preview event.');const n=s.native;const v={kind:e.kind,entity:e.entity??'0',key:e.key??'0',node:e.node??'0',value:e.value??1};if(!id(v.entity,true)||!id(v.key,true)||!id(v.node,true)||!integer(v.value,-1,1000000)||v.entity!=='0'&&!find(n.entities,v.entity))throw new Error('Preview event has invalid identity/value.');if(['Interact','Kill'].includes(v.kind)&&v.entity==='0')throw new Error('This event needs an entity.');if(v.kind==='Interact'&&v.key!=='0')throw new Error('Interact uses no event key.');if(v.kind==='Kill'){if(v.value!==1)throw new Error('A kill contributes exactly one.');if(v.key!=='0'&&!find(n.encounters,v.key)?.actors.includes(v.entity))throw new Error('Kill actor does not belong to that encounter.');}if(v.kind==='Objective'&&!n.quests.some(q=>q.objectives.some(o=>o.id===v.key)))throw new Error('Choose an existing objective.');if(['Kill','TriggerEnter','Objective'].includes(v.kind)&&v.value<1)throw new Error('Progress events need a positive value.');if(['TriggerEnter','EncounterFinished'].includes(v.kind)){const def=find(v.kind==='TriggerEnter'?n.triggers:n.encounters,v.key);if(!def)throw new Error('Event target is missing.');const expected=v.kind==='TriggerEnter'?def.entity:def.arena;if(v.entity==='0')v.entity=expected;if(v.entity!==expected)throw new Error('Event entity does not match its target.');if(v.kind==='EncounterFinished'&&![0,1].includes(v.value))throw new Error('Encounter result is 0 or 1.');}if(v.kind==='DialogueChoice'){const t=find(n.dialogues,v.key);if(!t||!find(t.lines,v.node)||!integer(v.value,-1,7)||(v.entity!=='0'&&v.entity!==t.speaker))throw new Error('Invalid dialogue choice event.');v.entity=t.speaker;}else if(v.node!=='0')throw new Error('Only dialogue choice events have a node.');return v;}
export function previewEvent(s,event){if(s.queue.length>=128)throw new Error('Preview event queue is full.');s.queue.push(normalize(s,event));return previewTick(s,0,s.player);}
export function previewChoose(s,index){if(s.dialogue==='0')throw new Error('No conversation is open.');return previewEvent(s,{kind:'DialogueChoice',key:s.dialogue,node:s.line,value:index});}
export function previewTick(s,dt=0,player=s.player){if(!finite(dt,0,1)||!vec(player))throw new Error('Preview tick needs dt 0–1 and finite player coordinates.');const next=clone(s);next.commands=[];next.time+=dt;next.player=clone(player);for(const r of Object.values(next.rules))r.cooldown=Math.max(0,r.cooldown-dt);for(const t of next.native.triggers){const st=next.triggers[t.id];if(t.entity!=='0'&&!next.entities[t.entity]){st.inside=false;continue;}const owner=find(next.native.entities,t.entity)?.position||{x:0,y:0,z:0};const delta=['x','y','z'].map(k=>player[k]-t.center[k]-owner[k]);const inside=t.shape==='Sphere'?delta.reduce((a,x)=>a+x*x,0)<t.extent.x*t.extent.x:delta.every((v,i)=>Math.abs(v)<t.extent[['x','y','z'][i]]);if(inside&&!st.inside&&(!t.once||!st.fired)){if(next.queue.length>=128){st.inside=false;continue;}next.queue.push({kind:'TriggerEnter',entity:t.entity,key:t.id,node:'0',value:1});}st.inside=inside;}
 let processed=0,actions=0,checks=0;const apply=a=>{if(++actions>256)throw new Error('Preview action budget exceeded; state preserved.');action(next,a);if(next.commands.length>128)throw new Error('Preview command budget exceeded; state preserved.');};while(next.queue.length&&processed++<32){const e=next.queue.shift();if(e.kind==='TriggerEnter'){const t=find(next.native.triggers,e.key),st=next.triggers[e.key];if(t.once&&st.fired)continue;st.fired=true;}if(e.kind==='Kill'){if(!next.entities[e.entity])continue;next.entities[e.entity]=false;next.commands.push({kind:'ActivateEntity',entity:e.entity,value:0});if(find(next.native.dialogues,next.dialogue)?.speaker===e.entity){next.commands.push({kind:'EndDialogue',key:next.dialogue});next.dialogue=next.line='0';}for(const enc of next.native.encounters){const st=next.encounters[enc.id];if(st.progress===1&&enc.actors.includes(e.entity)){st.defeated.push(e.entity);if(st.defeated.length===enc.actors.length){if(next.queue.length>=128)throw new Error('Preview event budget exceeded; state preserved.');next.queue.push({kind:'EncounterFinished',entity:enc.arena,key:enc.id,node:'0',value:1});}}}}
 if(e.kind==='EncounterFinished'){const st=next.encounters[e.key];if(st.progress!==1)continue;st.progress=e.value?2:3;next.commands.push({kind:'EncounterChanged',key:e.key,value:st.progress});}
 if(e.kind==='DialogueChoice'){if(next.dialogue!==e.key||next.line!==e.node)continue;const l=previewLine(next);if(e.value>=l.choices.length)continue;if(e.value<0){next.commands.push({kind:'EndDialogue',key:next.dialogue});next.dialogue=next.line='0';}else{const c=l.choices[e.value];if(!meets(next,c.conditions,e))continue;for(const a of c.actions)apply(a);if(c.next!=='0')speak(next,e.key,c.next);else{if(next.dialogue!=='0')next.commands.push({kind:'EndDialogue',key:e.key});next.dialogue=next.line='0';}}}
 for(const q of next.native.quests)if(next.quests[q.id]===1)for(const o of q.objectives)if(o.event===e.kind&&(o.entity==='0'||o.entity===e.entity)&&(e.kind!=='Objective'||e.key===o.id)){const c=find(next.native.counters,o.counter);next.counters[c.id]=Math.max(c.minimum,Math.min(c.maximum,next.counters[c.id]+e.value));}
 for(const r of next.native.rules){if(++checks>4096)throw new Error('Preview rule budget exceeded; state preserved.');const st=next.rules[r.id];if(r.event!==e.kind||(r.entity!=='0'&&r.entity!==e.entity)||(r.key!=='0'&&r.key!==e.key)||(r.once&&st.fired)||st.cooldown>0||!meets(next,r.conditions,e))continue;st.fired=true;st.cooldown=r.cooldown;for(const a of r.actions)apply(a);}next.log.push(`${e.kind}: ${e.entity!=='0'?e.entity:e.key}`);}
 for(const q of next.native.quests)if(next.quests[q.id]===1&&q.objectives.every(o=>next.counters[o.counter]>=o.required)){next.quests[q.id]=2;next.commands.push({kind:'QuestChanged',key:q.id,value:2});}if(next.commands.length>128)throw new Error('Preview command budget exceeded; state preserved.');for(const c of next.commands)next.log.push(c.kind==='Speak'?c.text:`${c.kind}: ${c.key||c.entity||''}${c.value!==undefined?' = '+c.value:''}`);next.log=next.log.slice(-200);Object.assign(s,next);return s;}
